#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Input and candidate cut positions.
    int n, requiredCuts;
    long long totalLength;
    cin >> n >> totalLength >> requiredCuts;
    vector<long long> cutPositions(n);
    for (long long& position : cutPositions) {
        cin >> position;
    }
    cutPositions.push_back(totalLength);

    // Greedy feasibility for a proposed minimum piece length.
    auto canSplit = [&](long long minLength) {
        int pieceCount = 0;
        long long lastCut = 0;
        for (long long position : cutPositions) {
            if (position - lastCut >= minLength) {
                ++pieceCount;
                lastCut = position;
            }
        }
        return pieceCount >= requiredCuts + 1;
    };

    // Keep left feasible and right infeasible.
    long long left = 0;
    long long right = totalLength + 1;
    while (right - left > 1) {
        long long candidate = left + (right - left) / 2;
        if (canSplit(candidate)) {
            left = candidate;
        } else {
            right = candidate;
        }
    }

    cout << left << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Store cells and accumulate the two one-dimensional summaries.
    int height, width;
    cin >> height >> width;
    vector<vector<long long>> grid(height, vector<long long>(width));
    vector<long long> rowSum(height, 0);
    vector<long long> columnSum(width, 0);
    for (int row = 0; row < height; ++row) {
        for (int column = 0; column < width; ++column) {
            cin >> grid[row][column];
            rowSum[row] += grid[row][column];
            columnSum[column] += grid[row][column];
        }
    }

    // The intersection cell was counted twice, so subtract it once.
    for (int row = 0; row < height; ++row) {
        for (int column = 0; column < width; ++column) {
            if (column > 0) {
                cout << ' ';
            }
            cout << rowSum[row] + columnSum[column] - grid[row][column];
        }
        cout << '\n';
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Sort once; each student's query is independent.
    int n;
    cin >> n;
    vector<long long> classLevels(n);
    for (long long& level : classLevels) {
        cin >> level;
    }
    sort(classLevels.begin(), classLevels.end());

    int queryCount;
    cin >> queryCount;
    while (queryCount--) {
        long long skill;
        cin >> skill;
        auto rightClass = lower_bound(classLevels.begin(), classLevels.end(), skill);
        long long bestDifference = numeric_limits<long long>::max();

        // Only the nearest available class on either side can be optimal.
        if (rightClass != classLevels.end()) {
            bestDifference = min(bestDifference, *rightClass - skill);
        }
        if (rightClass != classLevels.begin()) {
            bestDifference = min(bestDifference, skill - *prev(rightClass));
        }

        cout << bestDifference << '\n';
    }
}
